) AS (
  VALUES 
    (548::BIGINT, 'Personalmente me fue bien en QBI, pero le digo que si le cuesta esta materia mejor busque otro profe, pues no va a entender mucho, aparte que lo van a saturar con muchas tareas, honestamente las clases eran muy aburridas y la profe califica duro con los quizes.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2026-08-31T00:00:00+00:00'::TIMESTAMPTZ, 'e92d3bfbe503ffdaeb422540b0e8ac0fb35fadba4a9c3c732a1cb0408f3e374e'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'es buena profe pero si matricula muy tarde, la mayoria de clases son asicronicas y ud ud tiene que ser autodidacta, en si si le cuesta mucho quimica y no viene con buenas bases del cole le va costar'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-22T00:00:00+00:00'::TIMESTAMPTZ, '2610ce24f270793ef72625369bf5a3a5e0ac7ae5cc2d6d99f3914786e3ab2acd'::TEXT, ARRAY[568, 614]::BIGINT[]),
    (548::BIGINT, 'GOAT, para lab es super buena profe, es graciosa y explica super bien, deja los informes para hacer en la casa así que del lab se sale super temprano siempre (como 1 hr antes)los quizes son fáciles. la recomiendo para laboratorios ????'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2026-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'a39a94c720c70777df34c6ad0a32acd344d5cd6f00f3d9da7ca05d38ce1811e7'::TEXT, ARRAY[567]::BIGINT[]),
    (548::BIGINT, 'Complicada, en Química l es difícil de entender, me costó mucho entenderla y la clase en si es aburrida, y entendí más cuando alguien más me explicaba o investigaba por aparte, el lab es buena nota, solo que deja trabajos largos, sigo trauma con el cuaderno de actas, lleven lab si les gusta escribir'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2026-07-18T00:00:00+00:00'::TIMESTAMPTZ, 'da752b7ffb871ca719c736a6ce3a9ed223f78a71e32a16af7334cb1f083769fd'::TEXT, ARRAY[568, 567]::BIGINT[]),
    (548::BIGINT, 'el curso es sencillo le recomiendo que haga las prácticas los fines de semana o el día que tenga libre ,la profe si le pregunta algo obvio te dice que use la lógica, hace algunas preguntas que hace entender mejor la práctica y el informe, al final no es mala persona eso ya depende de uno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'c673b8caaf018a3a36ef2a969ad19b88fa34f2bd73254ab3cd8486b1df018712'::TEXT, ARRAY[567]::BIGINT[]),
    (548::BIGINT, 'Muchas veces explica sin ganas, explica sentada en la computadora con una foto del ejercicio en vez de hacerlos en la clase. No la recomiendo, por lo menos yo nunca le entendí mucho y me toco pagar muchas tutorias. Casi la mitad de la clase se quedó'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'f1afae9e1992aa94f899293c4e6d4e6499067ddd4b49fb2f353454ec08436856'::TEXT, ARRAY[573]::BIGINT[]),
    (548::BIGINT, 'Si van esperando un curso completa esperen que pierdan varias clases y que si se atrasa le des los últimos temas en menos de 20 min'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '7f76c3e103c459f880470e89d553195f92eb38bdc0f756a7d444fe386dbf1fc1'::TEXT, ARRAY[568, 614]::BIGINT[]),
    (548::BIGINT, 'No se deje engañar por la calificación que tiene, Maricruz es una excelente docente, desde el día 1 le gusta dejar claras las reglas del juego y aunque al principio parezca que va a ser un martirio, no lo es, ella ayuda bastante y explica cuando sea necesario, si hay que estudiar fuera de clase.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-27T00:00:00+00:00'::TIMESTAMPTZ, '9b4d3f8f15f6a41422a4fae5f0b513131641dbca470daee2b83833443e6e51c1'::TEXT, ARRAY[567]::BIGINT[]),
    (548::BIGINT, 'A mi la profe me pareció excelente, se preocupa por que de verdad usted entienda lo que está haciendo en el laboratorio, es graciosa y si usted estudia le va a ir bien. Para cursos como laboratorio la recomiendo un montón, usted va a aprender demasiado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2026-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e485c8363433714742467e9403dba7da3928293e0256a27b5784f472205f5033'::TEXT, ARRAY[567]::BIGINT[]),
    (548::BIGINT, 'Maricruz es excelente docente, ella hace que laboratorio sea un curso mucho mas ameno y facil de pasar con lo clara que es al explicar. Si se llega a sus clases con la actitud indicada se le puede sacar mucho provecho y ella siempre lo nota y lo aprecia, se ve reflejado en la asistencia que nos da.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2026-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'f15d6a0c27af32d09e8565444c8c34acbb26b3a3cbefca27b1f6c25d4344e62d'::TEXT, ARRAY[567]::BIGINT[]),
    (548::BIGINT, 'En un principio no me gustó como da las clases, pero ya uno se adapta, vea honestamente si usted no quiere mucha tarea y no quiere tener que hacer mucho quiz, no matricule. Pero si matricula pocos créditos y se logra adaptar a como la profe enseña, le puede sacar mucho provecho a las clases.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-04-24T00:00:00+00:00'::TIMESTAMPTZ, '17fc74454e0fcfdb546fbf3372d5f42367dceecc27b1f38c6dcb5ab9cac416e1'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Deja MUCHAS TAREAS, bastantes quizes, y no explica casi NADA, todo es tarea y tarea para qué usted aprenda solo. Si no sabe nada de química NO MATRICULE CON ELLA'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2026-02-26T00:00:00+00:00'::TIMESTAMPTZ, '35fb6d11445f43200585276bc50f7057d762b80b07f3a376b6d0852b30551ab8'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'La profe califica duro pero ella siempre está diespuesta a ayudar y resolver dudas, siempre hay quiz pero al final es de ayuda para ir estudiando para el parcial'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'eff78b043b5f6c37f58b3793b66f5deabc8761e42116d264ed08b8870e0c3413'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'para ella el valor que tiene uno como estudiante en sus clases depende de la nota que tenga en los quizzes o parciales, si sacó mala nota no espere ayuda de parte de ella, quizzes complicados, dura para evaluar.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2026-01-09T00:00:00+00:00'::TIMESTAMPTZ, '01c7f847870678dbac90f654626f38fb9a7ba93f48a5ebd23ea1cbceda33aaf8'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Es una excelente profe a la hora de explicar pero califica muy duro'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2025-11-14T00:00:00+00:00'::TIMESTAMPTZ, '3714e53c8e045f506e83c9a1c6c6881b668e85504bd9d655bdf6f3b644b358c4'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'La mejor profe que pude llevar, deja bastantes tareas morales que si uno hace y dedica tiempo si le va bien, si uno ocupa ayuda con algún tema, se lo explica hasta que uno entienda, la verdad la recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-11T00:00:00+00:00'::TIMESTAMPTZ, '69cfcada2787de75da1e4541a21af62c06a5394371d99a0f108e652c4098c5a0'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Profe muy dura, complica mucho la información, califica duro y las pruebas cortas son muy difíciles'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos exámenes']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'b0008a2beb092d6c65ff0234b38b0607ff177a919a2f1f6d1832216866d0d8a6'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Ud va a ser autodidacta. La profesora sabe del tema, pero no sabe explicar. Te hará la vida imposible para que pasés ya que evalua de manera muy extraña, y trabaja con material desactualizado. La cantidad de quices lo va a obligar a estudiar bastante. Si no se le da química, no matricule con ella.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2025-05-27T00:00:00+00:00'::TIMESTAMPTZ, 'bf4492ebde09f1aa00504329db661aabe118a52bab917fc53bbfbeb278949a66'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'A veces hace clases asincronicas con videos super viejos. Si usted no entiende casi que lo humilla delante de todos. Los quices son fáciles si lleva la materia al día, su horario de consulta nunca es accesible la verdad. Tampoco es que los profes de química del TEC sean buenos, es un 50/50 ella.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2025-03-27T00:00:00+00:00'::TIMESTAMPTZ, 'a779ad7365d5230faef3eb10c7a04ad35a6ed3901c9c506d672fda9570327de8'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Conforme avanza el curso la profe se dispersa un poco y deja muchas clases asincrónicas que bien si se entienden bastante bien, si no las ve, va a estar bastante perdido. Puede llegar a tomar una actitud bastante molesta si ve que usted no le interesa el curso.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'a5b50a69065ea808f97dfba906392fc778e272f58a30128841afe986df273a0a'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Para mí es muy buena profe, explica muy bien. Los quices y tareas que hace lo preparan a ud un montón para el examen. Está dispuesta a ayudar, pero ud debe mostrar esfuerzo por hacerlo. Llevaría clases con ella de nuevo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'e19a6d22342ab1f6bbd922a8b3c275d7e9ce64786884e72f5223d6f78231d984'::TEXT, ARRAY[567, 568, 614]::BIGINT[]),
    (548::BIGINT, 'Ella hace pocos quices, pero valen mucho porcentaje, lo bueno es que son muy similares a las practicas en clase. Ahora ella no es la mejor dando la clase, les recomiendo que se estudien la materia antes de la clase para que puedan entenderle mejor. Deja algunas clases asincrónicas.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-11-22T00:00:00+00:00'::TIMESTAMPTZ, '510d9eb53933b900ffc54e1fe16c93cf0c17838025e72de0560892455d9ad6f0'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Deja muchos tareas al inicio, pero créame, le ayudará y más si lleva Química II, es una gran profe, se preocupa por que el estudiante aprenda y vaya bien, deja mucho quiz y algunas clases son asincrónicas, si ocupa ayuda, se la dará, estudie mucho y pasa fácil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2024-09-09T00:00:00+00:00'::TIMESTAMPTZ, '40ab7dbbf89ceba1b8658df22bfc7d2f2ad8b43d22a50cb06e48ddd4de1f11a9'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2024-08-30T00:00:00+00:00'::TIMESTAMPTZ, 'b55420c090f87288539a7661fbea4ac07ab343f7f99c4e06f1cb62d64250767a'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'la mejor profe... Explica muy bien y tiene mucha paciencia pero si ve que el estudiante le pone.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2024-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'ef6ea7d0b7b6688ed67664c40052de7e6db6c300ba5dbdca03952910b0de4669'::TEXT, ARRAY[567, 568, 614]::BIGINT[]),
    (548::BIGINT, 'Su manera de enseñar no es la mejor para todos, los quizes son parciales literalmente. No le interesa mucho el estudiante y nunca te va a ayudar en nada. Además, quita puntos por cualquier cosa y buscarla para apelaciones es una pérdida de tiempo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2024-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'a920f205d41f182a5a4b9f7be177a8792e62079b1b784f9811591dff4c117875'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Explica sumamente clara la materia, de manera que todxs puedan entender. Deja quizzes pero son en su mayoría muy fáciles, y la manera en la que plantea los ejercicios se asemeja mucho a lo que viene en los parciales. Ella explica todo lo necesario para tener excelentes calificaciones!!'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2024-06-27T00:00:00+00:00'::TIMESTAMPTZ, '40d89534e5afecc61b15dc37e5284fa3458d1709fa612109b1be9d28b097542d'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'La profe da explicaciones bastante claras, deja varias tareas y las califica como parte de quices. Hace muchas clases asincrónicas, manda un video de dos horas de la clase grabada, así que llega a ser tedioso. En general es bastante buena.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '08d1bdaded8df61e3b191e46dbd92d8828902d4771c63d355648259f8a292c25'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Es una profesora justa. En la mayoría de los temas se le entiende bastante, pero a veces envía clases asincrónicas que si usted no se pone al día con los videos el curso se complica. Como dije, es una profesora justa, entonces es mejor mostrar compromiso en quices y tareas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'e76df841e0292ad13bbee4047ccb609f8ac194657595dfc73e7f8f0340e8460f'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'a pesar de que el curso sea presencial, gran parte de sus clases son asincrónicas, y solo deja videos, lo cual no es lo mismo que estar en clase y poder hacer preguntas a tiempo real. muy desorganizada. no utilizó nunca el internet, o alguna otra herramienta, para explicar temas que eran muy grafico'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-06-16T00:00:00+00:00'::TIMESTAMPTZ, '748e3dd1e56020552574c4fa4781fed055667400fecd307a36efc7740454b621'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'La profe sabe explicar muy bien, deja muchas tareas y quices pero sirven mucho para llegar y salir bien en los exámenes. Da buenos ejemplos con cada tema visto. Lo único malo es que no está atenta al correo o WhatsApp.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, '86de1582e5714b1b06adeb7f42ee35fba59dee0c6539af467049c4654a15dad9'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'El curso siendo presencial, deja videos de clases virtuales, los cuales luego funcionan para repasar, hace los quices necesarios para tener clara la materia, explica muy bien, solo enseña lo necesario para los exámenes y da tips'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2023-09-25T00:00:00+00:00'::TIMESTAMPTZ, 'b174fe08d211f45fbfd0a0e0e8287b3a0f8b001799b844e324ecaa799690c619'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'No la recomiendo la verdad, es demasiado vaga , la mitad de las clases eran asíncronicas donde el curso era totalmente presencial, no ayuda en horas extra clase y a veces no es clara con las explicaciones, matricule con ella si es repitente o es su última opción'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa']::TEXT[], '2023-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'e8fc521b704cf982ec8beff6eb2e13919c90f402419ab57568903b6e3ddd7864'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Se le entiende bastante la materia. Aunque el curso sea regular, deja algunas clases asincrónicas con videos propios claros (pero a veces duran más de las 2h de clase) y es importante verlos para no atrasarse. Los videos sirven para repasar. Deja ejercicios útiles para los exámenes. Va al día.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1f6f89404f5ec3c98201503efa3e26c247d85a82a9b71d319099bf89111afae8'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Excelente profe, busca distintas maneras de explicar para que todos entiendan'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '516a8c44c37a6dd89c69a53d48758f8d073197cf1942c79b5ba885440cd6ea54'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'nunca matriculen con ella, explica súper mal y no aclara dudas se enreda demasiadoo en clases y califica mal exámenes los quiz son regalados, puntos asegurados pero eso no segura buenas notas en exámenes!! si tienen la oportunidad de matricular con otra persona HÁGANLO'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '6964670a43d15459283a2164ccd12df3d011532f313bc84e5310ffff03780690'::TEXT, ARRAY[568, 614]::BIGINT[]),
    (548::BIGINT, 'La señora no ayuda en nada, no se interesa por los estudiantes, uno le puede entregar un quiz tarde por alguna situación de mucho peso y a ella no le importa, no avisa con tiempo si uno va a repo, he inválida quizes a final de semestre porque le da la gana, no recomiendo llevar el curso con ella.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'ffb6ff23ac4cd9255c323c00ef2a05736739c1671c8396ad3492ee922df5f78a'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'La profe dejaba asincrónica muchas clases y sustituía una clase de dos horas por 3 clases grabadas de 2 horas cada una. Solo hizo como 8 exámenes cortos y solo 3 se hicieron en clases, los demás se hacían en la casa'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '812222071338fcf992cd3a46727ab6db9cd6acf6d20e1bed8b99c1e37d9a27a8'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Es una buena profe, explica bien pero aveces deja mucho material audiovisual en vez de clases presenciales'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, '6197b7d83a37736b8448b4fb4561f13d279d32e67970dc114eb09990848cbafd'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Está bien. Explica en clase de manera clara. Fuera de clase es muy poco accesible. Así que si tienen dudas fuera de clases, otro profesor será mejor opción.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'a06e5e27ee42b95568ff3fc020ea459feda5ceeaac7f2aae939cc5f7c35cca01'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Hace solo 7 quices que se entregan por teams y da buen tiempo para entregarlos(puntos regalados), en clase no se le entiende nada, se hace colochos para explicar y se pierde. Para los examenes es mejor estudiar con el material de la catedra, las presentaciones y clases de ella no sirven para estudia'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-22T00:00:00+00:00'::TIMESTAMPTZ, '4e7c2ef4948447251e8faac3190700b6c565882ffd5b09558d660ea448d3568d'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Es una buena profesora. Explica relativamente bien, busca que en sus clases se entiendan bien los procedimientos. Las tareas y quices son buenas para repasar, entonces lleve la materia lo más al día que pueda. Es un curso interesante. Eso sí, NO LLEVE VIRTUAL CON ELLA, es un poco desorganizada.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'e7c49619006605b7d04863e2cc9aa92bce998c387cc5ca8922b6763b0951ad8b'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Muy buena profesora, clases bastante largas y cansadas, pero explica super bién, se devuelve si no entendemos la materia, los quices que hace son bastante largos, pero fáciles de hacer nada complicados y super buena gente es siempre atenta a dudas por WhatsApp incluso en horas de la noche'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'f76cdd350fa6b89180a5d55f9a86dc25a844dc6c4fea85545d7e35254925b05f'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Explica muy bien, pero por lo general va bastante rápido; si uno le pide que se devuelva, lo explica de nuevo. Si toma nota, escriba lo que ella va diciendo en lugar de lo que proyecta. Hace un quiz por cada tema. La participación en clase es muy importante.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '1bd5f5b58ad34332ddbd79f8e984c4a1677f3572ef7520bbaaf4b983acf7b278'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Excelente profesora! Explica muy bien, pero siempre va rapidísimo. Le gusta que uno participe y que vaya estudiando al día. Realmente buena.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '7703866dadfeb438b628934c10a378c422f92c7e129e2803462474a3eff14afb'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'La clases son un poco enredadas y explica rápido pero generalmente atiende las dudas y se devuelve si es necesario. No es ni la mejor ni la peor.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, '6449c8cdedea72c172df446fc583eed67ba27dbac5a7363bb3f03ab8f6ad65d9'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Me pareció una buena persona, solo hay que saber cuándo si y cuando no, la profe es estricta y un tanto bipolar, en realidad va rápido dando la teoría pero 100pre gracias las clases y eso ayuda a volver a verlas, me parece que da lo justo y nesesario para el examen.(no regala ni un 0.1%)'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'eebb3c6702c00582393403d9ee8cc2f4f03a30bf33f518d878e36b9e278cb4cf'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Si pueden evitarlo, no matriculen con ella. En clases virtuales se hacía mucho enredo. Explica demasiado rápido. Al preguntarle algo responde con otra pregunta. Dejaba los quices para la casa, pero en grupo y usualmente los ejerecicios eran muchísimo más complicados que los vistos en clase.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos proyectos grupales']::TEXT[], '2021-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'fe97f0b08f0b7e13b295af568d8e08cc2cfece33764175b7eff13828cd4f53c1'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'La profe es muy buena, pero la manera en la que ha llevado con la virtualidad no tanto: a veces se enreda y va súper rápido con los temas, en ciertas partes ni se le entiende de qué habla. Deja muchas tareas y dura mucho en calificarlas casi hasta el final, hace muchos grupos.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Pocos exámenes']::TEXT[], '2021-11-17T00:00:00+00:00'::TIMESTAMPTZ, '78a7104e7e148726029bad05f5e51d08c8063b1501bbe5be09f1b6d64cee4c96'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'No se porque tiene tan malos comentarios, a mi me parece una profe excelente, aveses va rápido y es un toque grosera, pero tampoco hay que ser de cristal, aveses simplemente es sincera y le interesa que usted aprenda, almenos virtual es buena profe.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2021-08-19T00:00:00+00:00'::TIMESTAMPTZ, '69b5f390a3ec376a1c6415ae52f42a03e84af4bf76121f8599b2d8c3795dca0b'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'La profe no es mala pero va demasiado rápido y es un poco grosera pero se preocupa para que a todos le vaya bien'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-07-30T00:00:00+00:00'::TIMESTAMPTZ, '258dd72403753f4c1266a4d341219986951fa5cac76ee049742e0b1fc085339a'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Es una excelente profe. Explica muy bien y claro. Si no pasan es por no poner atención.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'bb444be97910eb77eb792091a056fe1ea3cd65733ff83a634c0583eb0c0880b0'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'ES DEMASIADO BUENA PROFESORA, ESTRICTA Y NO LE GUSTAN LOS PRETEXTOS, PERO PARA MI ES LA MEJOR QUE TUVE MI PRIMER SEMESTRE... Y NO PUEDE EXPLICAR MEJOR ES SUPER CLARISIMA, Y BRINDA ALTERNATIVAS PARA AYUDARTE.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2021-07-24T00:00:00+00:00'::TIMESTAMPTZ, '2d0fa1d1deba0470ba827bc45555ca9b299272f7d5d14328ebb02ae0c6c6b4ee'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'La profe repite las cosas cuantas veces sea necesario, no le importa afectar al estudiante en las notas, pone quices en los que se aprende bastante y siempre se va a obtener una buena calificación. Algunas veces puede ir muy rápido pero si uno se lo menciona se devuelve.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'e5e5c0c5248eaf5096300dc405b3ebd75692a19444332a02f6bf534c35d0073b'::TEXT, ARRAY[573]::BIGINT[]),
    (548::BIGINT, 'La profe es muy buena lo que sucede es que aveces se enreda hablando y suele ser un poco grosera Los quices son regalados puede ganarse el 20% sin problema'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, '0e4897c1788c70346167160d8fccd8a7f6dbde260b3fd49165c30a041d69471a'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Es bastante fácil si usted llega con unas buenas bases de química del cole, a veces puede ser un poco grosera pero en general es una buena profe explica las veces que sean necesarias. Los quices son demasiado fáciles .'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, '79987ec3aa0547b13690ebf63c3c3e970922ea1d34d38d8a79e4ac82ededed69'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, '9f3f56fb36c5f874bc42dceb189dd7f0b0ebe2e0df2fc67c804a3ab1d1763d91'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Aunque los quices y tareas son bastante sencillos, cuesta mucho entender lo que explica en las clases si no se tienen bases, se enreda hablando y es un poco grosera cuando le hacen preguntas.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'e4b0aff99e5b1df24523f2e9fa556ab7608f6b6b31a4b11074736a0d0cb6114b'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Es excelente enseñando, se enoja si hacen trampa (hasta por lo más sencillo de ayudarse entre compas) si se entera los regaña a todos (hasta a los que no saben de lo que haya pasado) Es inspiradora, entiende a los estudiantes, no le sabe mucho a lo virtual pero se esfuerza. Buena persona.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-07-18T00:00:00+00:00'::TIMESTAMPTZ, 'b67e81e03a9496bbb083d2725ad387dbe3204bd5fafd6e8025c41bf6f0291139'::TEXT, ARRAY[573]::BIGINT[]),
    (548::BIGINT, 'Excelente profe, siempre trata de dejar todo súper claro, no es tan paciente pero nada fuera de lo normal.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '42f526b4fa097cb0664d8ea8e2084f8a159e02d942c43921d55ec039aeb6375e'::TEXT, ARRAY[567, 568, 614]::BIGINT[]),
    (548::BIGINT, 'Explica bastante bien la materia y se devuelve si no se entendió bien el tema. Deja quices muy sencillos. Lo único es que a veces explica muy rápido pero si uno le dice, ella se devuelve y lo hace más lento.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '847ddb25a8b6944a5f1d4798b79b94ed51d60d2ee6bdd7501550477a7bc1380a'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Yo no le entendía muy bien a esta profe y explicaba muy rápido. Si usted tiene buenas bases con Química ni lo piense, matricule. De lo contrario va a ser un caos. Entendía mejor en las tutorías de Química.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-07-05T00:00:00+00:00'::TIMESTAMPTZ, '1a5f9a41c3f9620bb75022bcb6f2a9118dbef01fbd92ab43da33ddf575464ff6'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Le gusta que las cosas queden claras y no le importa explicar varias veces lo mismo. Deja quices fáciles. A veces explica demasiado rápido.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'a953f844831b0a3bf1e0525b5b75a6820a3dcb66668b908c4372edb253f6daca'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Virtual: La profe a veces se altera explicando, más si le hacen una pregunta. No está tan difícil, pero si matrícula con ella mejor lleve éxito académico. Los quices son fáciles, los deja para la casa.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-06-15T00:00:00+00:00'::TIMESTAMPTZ, '90de31dc8fe4e22c95b825e9637070a47cbd88f9e5eb268ce8bfb5b5e0939f18'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'd0d57536fc9cf9bdc0584cf748969c9bd75fbbd4e65bc570eb9969dabaab271e'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Para química I es excelente, quizás de las mejores. Para química II es buena, pero hay mejores. Si piensa matricular con ella no lo haga en el ultimo grupo del día, porque al final del semestre le da por subirle la clase del grupo de la mañana y eso en lo personal no me gustó.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'd97d9e67638b5931879551b23479ae66dbe340d9eef25dd1ffd55ccf82740993'::TEXT, ARRAY[567, 568, 614]::BIGINT[]),
    (548::BIGINT, 'La profe se preocupa de que los estudiantes estén entendiendo. Yo llevé el curso virtual con ella y es muy buena como profe, tiene mucho conocimiento que transmitir'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '65f05141fe029a0646a2faf47b3b6c74f7dbf7cf49d935a5fc1e0b35745ea799'::TEXT, ARRAY[567, 568, 614]::BIGINT[]),
    (548::BIGINT, '{Virtual} Cuesta mucho entenderle, pero no es la peor opción. Clases largas y a veces aburridas.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '272aaf90da6a33cc0859e2d41afb930c723c5bf08b65ba83290402b50101f010'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'El curso en general requiere que uno le ponga, ella explica bastante claro y repite las veces que sean necesarios aunque aveces se le nota un poco como la desesperación, pero siempre se asegura de que haya entendido. Deja bastante material de apoyo, por mi parte con las clases de ella bastaron'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '3717b55b048ac3f3f295aeddb602a56fcd04b357b105c518b293e6f3282d2d38'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Lo que hace es dejar una clase grabada y subirla, fatal la verdad. Tiene que ser autodidacta e ir a tutorías. Se enoja demasiado rápido y si no quiere nunca le va a contestar aunque vea su mensaje.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, '2d71116febe5d68c9d47aa56e9fcd27f9d6485711438e0e2a69fc1a686dbd5c1'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Es una Profe muy buena, el curso se pasa solo el (QB 1 Y QB 2) con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-30T00:00:00+00:00'::TIMESTAMPTZ, '0d435af07cce6d58c055548d720863b6511d28bb2a78842882ad29983fdffcf1'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'La verdad si uno lleva el curso con la profesora, necesita ser autodidacta porque a veces no se le entiende, sin embargo, la profe ayuda y trata de que todo el grupo vaya bien, trate de llevarse bien con ella y aprueba el curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '577eb5d38f6d749d3d3cff9325c3cb670e19a9ede00a4f193fcbbe4dc70619aa'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'La profe no es mala, si no que se enoja demasiado rápido, explica demasiado rápido, se estresa demasiado rápido, ella intenta ser cordial pero cuando uno le pregunta por aparte en veces ni responde y todo lo enseña difícil. De mi parte yo pase el curso gracias a las tutorías pero no a la profesora.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'f996fc779a5e74ce6350cf174a3d18910b3c17e9cbd21608fbf28e3edb9df9b8'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'un amor de profe, se preocupa porque entendamos, hace evaluaciones fáciles y siempre está atenta a las necesidades de los estudiantes. Me parece que está tratando de mejorar su calidad de enseñanza :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-21T00:00:00+00:00'::TIMESTAMPTZ, '6cdfa0a48bbcea219763671e848c89ae4df76413b654213b12767d37a633e127'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'La profe en modalidad virtual es excelente, tanto para química I como para química II, explica muy bien, pero suele hablar muy rápido, hay que poner mucha atención!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Clases excelentes']::TEXT[], '2020-09-30T00:00:00+00:00'::TIMESTAMPTZ, '9228f02646864cbf1fffbe51c480400631eba3afeb10a98bdbde72034f7d4fcf'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Es súper buena profe y muy linda persona, no entiendo como tiene nota tan mala. Siempre ayuda mil veces cuando uno no entiende, tiene mucha paciencia y explica todo muy bien, la clase a veces se hace un poco larga pero hace ejercicios para practicar y para los quizes da varios intentos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-30T00:00:00+00:00'::TIMESTAMPTZ, 'aabe42c4c51a18c074b326fb7cd2a9ab71c7f91e8ee1ced48a74ff0029934c52'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'buena para la modalidad virtual'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'ff12a4e5c840c29b0ac240f3a3baddfc02cb5b3449f3d38e7f12443ca55e3a68'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Lo único malo esque las clases son aburridas pero en general es buena profesora, se preocupa por el estudiante además en la modalidad virtual es muy atenta, recomendada.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '40b69a8cc86209a4d41db579ce8d2440a43eccf54e4cf1d4a54dcc14e54a2ab3'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'De alguna forma se preocupa por los estudiantes especialmente en las autoevaluaciónes y quices, pero sus clases son muy pesadas y aburridas, y por lo general daba importancia a cosas sencillas y otras más complicadas que podían salir en el examen, las dejaba de lado'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'ae52092ad9aa521f6cb89e2de8a13517dac57e5cb7ad05d56d247e401659e044'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Es dificil pero no seas marik, es el tipo de profe que vale la pena y de verdad se aprende'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, 'a84162447611e2ee9ee70b63fa5c48ae7f5628da653531fafc9b29f3ca41efcd'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'La profe es comprometida, eso no se puede negar, el problema es que de forma presencial casi no se le entiende, en forma virtual fue de excelente ayuda, más con la implementación de las auto-evaluaciones.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'f02960b1477e2d28b0dca9c4adeed24e7be76027445284983426b99e70e573f4'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (548::BIGINT, 'Me gusto mucho las clases, se preocupa mucho por el estudiante. Es muy seria pero excelente. Habla un poquillo rápido, por lo que uno tiene que poner atención y concentrarse. Deja las grabaciones. Espero matricular con ella Química II, muy recomendada.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-11T00:00:00+00:00'::TIMESTAMPTZ, 'b916c64b812c5d94783d8ed7f8f6fb5672b758ddcdc4bdc89c49371c46bd54cc'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'llevé virtual y la verdad no tengo quejas me sorprende ver bajas calificaciones. Explica muy claro se preocupa porque todos entiendan, si tiene que repetir 10 veces las repite. De lo poco que recibí presencial, deja mucho brete, generalmente tablas o resúmenes, pero sirven muchísimo para estudiar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-11T00:00:00+00:00'::TIMESTAMPTZ, 'a0fda27dc5f2040fa6056e462cc3a750a75ad2c834eae86be3912796f51b6a14'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'En lo que respecta a modalidad virtual es bastante buena y comprometida aunque si habla rápido y no da tiempo para apuntes por lo que le sugiero de verdad volver a ver la clase y hacer los apuntes pertinentes, por lo demás buena profesora al menos virtual'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Brinda apoyo']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, 'a60c440819a35b7a165f9b3b2909b649c8f9282f8544f9eb97919acca276d43e'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Me sorprende su calificación, en la modalidad virtual es muy comprometida. Se esfuerza por hacer a los estudiantes entender.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-05T00:00:00+00:00'::TIMESTAMPTZ, 'a62552c7a6d51e4bb8349d33b69c0356fc58ebc029da05f585219394ea771c5f'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'No entiendo porque tiene calificación tan baja. Yo recibí química 1 con ella, modalidad virtual, y siempre explicaba muy bien, los 40% de Auto evaluaciones y Quices los tienen asegurados y en clase se preocupa porque todos entiendan, y siempre responde dudas hasta que todo quede claro.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, '392af2bca18e5db6a584e3797107eaf4f8976944f906d3e50c1aa915eda3e4c8'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Es buena profe, prepara muy bien para los exámenes. Modalidad virtual: 9/10'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2020-07-15T00:00:00+00:00'::TIMESTAMPTZ, '9c41181927652a2b24660831f1c7afda2fd254bf3e4bebaed6a8f9e76720388e'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Es dificil pero te prepara bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2020-03-12T00:00:00+00:00'::TIMESTAMPTZ, '3875ff001dada32fed3c0598e11c819d86f602e64ca225fe0821a5e617c36219'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'La profe no es tan mala ( por mi experiencia) como la gente dice, sin embargo si es la primera vez que lleva el curso puede q se le haga difícil ya que ella a veces explica las cosas pero "al aire" por lo cual es importante poner atención y tomar apuntes. Explica lo justo para el examen'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2020-02-11T00:00:00+00:00'::TIMESTAMPTZ, '10c50fa572da2437e2b95ccf5b4a0704b03232fcd387a3a30cc6e57f0ca48437'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Bueno, la profesora para mí es buena porque explica las cosas con cierta facilidad, no como otros profes. Socializa con los estudiantes lo que hizo divertida la clase en mi opinión. Ayuda con crédito extra.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-09T00:00:00+00:00'::TIMESTAMPTZ, '4773b78c1f3a9f672d3143f623450c86fd417a6e66e92726f96e4a1272ec8c48'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'En química 1 no me pareció tan mala pero en química 2 tras aburrida su clase me pareció un poco brusca , ya que ponía a los compañeros en vergüenza a pasar al frente y nadie quería preguntar nada porque ella en vez de resolverte la duda te decía que ya lo debías de saber y lo tenias q resolver'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '33764541b7d2933c6d5620782758f6cb60a3e193838be7af2f894a7b62d502ef'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Nunca entendí porque tiene tan mala calificación. Es buena gente, ella hace muchos quices parecidos al examen para que uno aprenda. Se interesa mucho porque el estudiante aprenda y hace muchos ejercicios. Si creo que para recibir con ella hay que llevar buenas bases de química.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Brinda apoyo']::TEXT[], '2019-12-11T00:00:00+00:00'::TIMESTAMPTZ, '5e1dbe9372c483f9591a1fb0a08d497746d2732ef38a7cfef3d57760e332788e'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Muchos de los comentarios son verdad, por ejemplo de las presentaciones de Power Point. diria que no es la mejor ni la peor para llevar el curso. Aveces se enreda con lo que dice.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '81c8cbd273cce3ac7fa7d5d8338b875c5fdcbf83344905c09e730e72eb2acc85'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'En QBI no estuvo tan mal, pero NO LLEVE CON ELLA. De la clase de 50 personas más o menos pasaron muy pocas. Dice que no tomen apuntes que ella pasa las presentaciones y no lo hace. Se distrae un montón, ni ella sabe lo que habla. PÉSIMA.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores']::TEXT[], '2019-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'd3c8abbbc1f14df01df2137cf49dd5fbcf2b7e9b9a43646b66c2a0d6676e29d0'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Pésima, piensa que uno va a su clase a escuchar cosas que ya uno sabe, si le preguntas algo te responde con cosas de 3 temas adelante y 7 atrás, no aclara nada, a veces solo se sienta y lee lo que dice en las presentaciones. Mejor vaya a clases de otro profe y pregunte cuando hay quiz.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2019-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'eeeff660049470b608669db5b0e5556bcfd9cf73f15c28a4df6c8bafbf44d209'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Pésima profesora, no explica nada, a veces se queda sentada leyendo las presentaciones. Hace los quices difíciles mientras que no se le entiende nada. Es mejor dejar de ir a clases y estudiar por su cuenta.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '2427efb6363dba047c209311fe8afbe4d8456127fe45e5fb9e8b48b9cdb9f74c'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f8b889aa931eabf5d3a72a7fa939977adbf9d98c6f52280de7bd35ada1206e68'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Puede buscarse un mejor profe creame jaja. Es mejor ir a tutorías.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'b03aa1396fae75b18203e6a4c02456da3d92756493bc42935ff14883df5c1de9'::TEXT, ARRAY[568, 614]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'b031dd31a0cf197e7777a8a65d33d90762fae75dc42d830f4a1735fe14e73cfb'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '47d7a763a71d55c00a2edce26b742b3604c99c6352cdc78ce59da2fcd2a3bd02'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Debe tener buenas bases del colegio para entender, complica mucho los temas sencillos y en ocasiones hace que los estudiantes se confundan más. Excelente persona y muy comprensiva. Brinda un ambiente de confianza.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'd51099dfa7c864e87089488a1965e8b9ed18d50d310e91c5c584cca92506c557'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Es buena gente, se preocupa porque entienda los estudiantes, son muy prácticas sus clases (casi no explica lo teórico) y sus quices y tareas ayuda mucho para practicar para el examen :)'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Brinda apoyo']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '1ab7ae74d4f5f230e08112de5b8e3f9e5fe8f2d0faf4fe4d32cab6e3e851f6cc'::TEXT, ARRAY[568, 614]::BIGINT[]),
    (548::BIGINT, 'Es cierto que con ella es mejor tener buenas bases del colegio, ya que a la hora de explicar lo hace muy confuso. Si usted ya tiene conocimientos entonces apéguese a eso y repase con lo que ella proponga, no se confunda. Deja algunas tareas y quices muy sencillos.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '65b1224dba3df695bdcff1b3803586eb1b748d4d6ded2884f8143c509a029d0a'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Es mala, si usted viene con buenas bases del cole no importa, de otra forma NO matricule con ella. Es muy confusa, casi no se le puede hacer preguntas, porque dice que le "deje terminar la idea" por aquello de que lo que va a explicar ya le responda la pregunta. Revisa pésimo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, '2b6884e8063a37c9ab6824bfa7bc141adf017e147abd749b2937948e02f48e49'::TEXT, ARRAY[4253]::BIGINT[]),
    (548::BIGINT, 'Al inicio tenía como miedo por los comentarios negativos.. Al finalizar el curso, me di cuenta que en realidad si se le entiende bastante, a excepciones de algunos temas mínimos, pero en general me parece buena. Y aunque no revise las tareas, sirven bastante para estudiar.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Muchos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'ca10f7f0221f02b421054cfed05d5785ec9b37a1a667d8b6f5ad8b1e11882bc0'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Envia a hacer fichas que quitan mucho tiempo y por lo general no ayudan mucho. No se le entiende muy bien. Pero tiene buenas intenciones en que uno aprenda, como persona es buena gente.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-08T00:00:00+00:00'::TIMESTAMPTZ, '09f979448e6bc400a2f41269386b20f5b1b932d662970bf30ebf89ccbb926196'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'No es mala, la verdad se le entiende muy bien si uno de verdad muestra interés. Deja tareas que no cuentan, pero si uno las hace le va súper bien en los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-15T00:00:00+00:00'::TIMESTAMPTZ, '623cb1a1834fc1526d31eca345c8f46e7379af077ccadc111205e1aed69ffda4'::TEXT, ARRAY[567, 568, 614]::BIGINT[]),
    (548::BIGINT, 'Mae, legal sol vine a recordarle al mundo que ella no es una profesora, es una señora que lee presentaciones y no sabe explicar, ni se molesten, es mejor llevarla solo o otro semestre a llevarla con ella'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2019-05-04T00:00:00+00:00'::TIMESTAMPTZ, 'fabe79e519c9b6fb279bd444d6053537028dc13039246b94ddc15b9d2ecaa10a'::TEXT, ARRAY[567, 568, 614]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-03-15T00:00:00+00:00'::TIMESTAMPTZ, '99d79d6da1e87063b59fe20979b2a96bc23a02cc39fc25936f548018c742b193'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (548::BIGINT, 'En lo personal, llevé el curso con ella. Al principio sentí preocupación debido a los comentarios negarivos. Sin embargo, me pareció muy clara, ayuda un montón en clase y se hacen bastantes prácticas. No sé si será diferente dando Química Básica I pero para Química II la recomendaría mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'ec9e6faeec989178eede199728fbc27eda42e964040f233d2506035b1e1e8ba0'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'No es del todo mala, algunas cosas las explica bien y en otras se complica un poco. Es buena gente, ayuda si uno se esfuerza. Con los quices hay que tener un poco de cuidado, la mitad los deja para hacerlos en la casa pero hace muy pocos. No es fácil pero se puede pasar.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, '78ccbbb0c5d0c93b89003bea0294e5e562189c36df56b874ae009121db9e6a05'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Es una profesora de lo peor que hay. No tiene interes en sus alumnos, no explica bien la materia, enseñar no es su profesion y matricular el curso con ella es perder el tiempo!'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-07-24T00:00:00+00:00'::TIMESTAMPTZ, '8187a290d4280c6c833fe4de468b119e74436deedaf10235787c79d653df0831'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (548::BIGINT, 'Tome su clase sin saber a lo que iba. Luego de 6 meses de clases llegué a la conclusión que algunos estudiantes están mejor preparados para dar esta clase. Aburrida, desordenada, impuntual, en fin no cometas el mismo HORROR que yo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos exámenes']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'e2fb3f7c7a9709b4c4699814718b12314aacc92896a5427e7514188c01ce0ce5'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a95c1a13fb6d37a24a9ad8e976780299854b565eb0a98b5ec4c52c6123677ac8'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Buena profe, no explica mal. Deja muchas tareas pero casi ninguna la revisa, solo las entregables. Tarda bastante en calificar. Hace bastantes quices.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, '7a16055d0c6e5cda7e497383e6dc38a9d8d9da008dbfe621c1241967a93277d5'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Es una buena profe y persona. Hay que tener un poco de bases para poder matricular con ella. No es aburrida, recomienda usar el libro que se usa en el curso, sin embargo no es necesario, ya que todo lo que explica es lo que entra en los exámenes.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, '11f1222668c71a6c7e74062ecc9f7f849cc7ef086a0a89d48b98dabd965cc3e0'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-11T00:00:00+00:00'::TIMESTAMPTZ, '425cd0d771567968be73d36749325549084bf7d9f4bc134b07e6aa4b480b7712'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (548::BIGINT, 'Le falta dar respaldo con libros y presentaciones.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2018-05-05T00:00:00+00:00'::TIMESTAMPTZ, '0ba8f179f5ac4003c42a3feaf617fdcb31b5121200b57d5ec66ea962b5bc4f00'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Es la peor profesora que hay, no explica toda la materia que entra en el examen y la que entra, no la explica bien. NO matricule con ella porque va a llevar PALO mae.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-04-23T00:00:00+00:00'::TIMESTAMPTZ, '0a3fc974782f94d6dac1a858da9cc2e85fa000eb88c5295b68d075596d0fd61e'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'De lejos la peor'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'b4d7a704dff37917d528e53d912d9926281d5bd0a96ae66645d2e8353282b21b'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'No explica bien, es sumamente irresponsable, una vez mandó la materia tres días después del examen y si uno estudia solo lo que ella enseña de fijo se queda. No recomendado para los que llevan química por primera vez o les cuesta'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '0f3f2ba40c11791ddffe281812a9ccc9dc7d8812da113a15a6252d8a4f2ab248'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Para mí explica bien, pero sí hay que estudiar porque hace quizes constantemente (ayuda a la nota). Siempre llega tarde. Casi no deja tareas'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-25T00:00:00+00:00'::TIMESTAMPTZ, '3134a3dcd2dd7ca2be1266a1d15776d91b2ad7548ad867365bbb4af6b2db13db'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Es agradable pero muy despreocupada, suele llegar tarde y muchas veces no se le entiende la materia'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '362ec84229dcc185fc97b0bbf1d0d97237f7cbed60f690a5046160971e640dea'::TEXT, ARRAY[568, 573]::BIGINT[]),
    (548::BIGINT, 'Si usted nunca ha llevado química, no matricule con ella. No sabe explicar claramente y lo trata a uno de manera despectiva si hace preguntas. Si estudia con solo lo que ella enseña no va a pasar.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Asistencia obligatoria']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '2383fe7754d696df42a03b84e2d66ef570637c222587ed3c9b90fbde293523d6'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'NUNCA matricule con ella. Va a tener que estudiar solo'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-21T00:00:00+00:00'::TIMESTAMPTZ, '1c5b371cb47c7efc3e4fdb7dbae83e61c73f1017a9c7bd59001a7cbfd079ba2b'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'es la peor profesora'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, '50aa1697b8ac9cda5a92390870352f8f920cda0c8a4d6136486b7bb79d4fd209'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Califica en base a sus emociones al momento de. Es una compañera más, todas las clases se las lleva a pura presentación. Si quiere atrasarse y bajar su ponderado, lleve la química con ella.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-09-22T00:00:00+00:00'::TIMESTAMPTZ, 'b130d4c03fed4bfb87063c6f2973599bd9bce74f535d2f4260f888310e6f4c32'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Enrreda antes del examen!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-19T00:00:00+00:00'::TIMESTAMPTZ, '257c96a08d271f1247c245a831b61533d124738ddbc16a84a816238d18f8a7da'::TEXT, ARRAY[568]::BIGINT[]),
