    (548::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'ad881569a8822ea3788b8f806732bc0f20034d5b5827f7f5a0b0928f5bfe9c2f'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (548::BIGINT, 'No explica bien, le molesta aclarar dudas, llega tarde siempre'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'a4ab5cb40d4f11253cf28da27a051d461fb053c7baf25e04edd2c179d5460ebc'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'No explica bien.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '4a2106252dc293aa59f7b0e8be52cdb0e61b50535a524febc44a8861f784f9e8'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'En algunos temas se confunde, especialmente los del inicio, a veces dice detalles mal, o al reves, pero especialemente al inicio. Con el último tema, estequiometría, se la jugó, explico bastante bien y se le entendió, no es tan mala, pero si puede mateicular con alguien mejor sería genial.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'c3500c849e46efcd94c7a8fb1371164eb92c49fe2cad08744eb1a6c63918a10c'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (548::BIGINT, 'La verdad no me pareció tan mala. Transmite sueño y pereza, recomendable sentarse adelante.Quices fáciles. Califica lo normal.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-16T00:00:00+00:00'::TIMESTAMPTZ, '7277dff0f1b23e3cdd07c4b275533b3ac0679b8594ea69b9e51b540ceed3ee31'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'No explica muy bien. Habla muy bajo, hay que sentarse adelante si o si. Quizes fáciles. No regala puntos en lo absoluto, ni con el MADI. Aclara todas las dudas,solo es de preguntar.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'cf3b2456771e3772a093f7f60a8700b4205964a4b497686e785949d25b3ba524'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Es un bostezo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '31a9c57cb3ed21d897306153f37d8b3f2114d9c10361a4927f5cb9ee7d19c22d'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Pésima. No tiene vocación de docente, no se explica bien y no muestra el mínimo interés en el estudiante. Le trasmite la pereza a uno. Si matrícula con ella considérese autodidacta.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '7f5ac0f0e3780a6454032a287feafa0a252c04d3171c52cf7c686b2d9f8a9de8'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'f3b7c1fde52b45f4a28f346768a2c08b26202db6ef2410a840e2ca443bd8a24d'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Pésima profesora en general.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-05-30T00:00:00+00:00'::TIMESTAMPTZ, '1b2b3e0e266f8800c5b7b4fbcb3889ec4ac9ac2dc3cef855d8f5403010584428'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Hay profes mejores. Ella asume que ya se saben las cosas entonces no explica muy claro.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'b8497dec2511ada172bb80fbbce5ec656542cb9b20e45472722687ac9a09b878'::TEXT, ARRAY[567]::BIGINT[]),
    (548::BIGINT, 'La Profe cambio mucho este último semestre. Lleve quimica 2 que es un curso rudo y me fue muy bien. Ella ahora explica y se toma el tiempo para hacer los ejercicios en clase y da práctica extra. Los quiz es no son muy difíciles. Además da repaso antes del examen. Ahora si la recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-11T00:00:00+00:00'::TIMESTAMPTZ, '07f6be0dc82c3241d3ed3f81dcf06b2a8866e9cb1f40c9c1e863992b38a0de5d'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Muy mala profesora, llega con pereza a las clases y lo que hace es leer presentaciones power point, hace comentarios fuera de lugar, lo que aprendí fue por las turorías.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-18T00:00:00+00:00'::TIMESTAMPTZ, '4f9a72a5a468c2599cad509b4ece2b3e11188ee271394043c9eba6b59e39993d'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'La peor, muy mala en todo sentido. Mejor esperar al otro semestre que matricular con ella.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-19T00:00:00+00:00'::TIMESTAMPTZ, '6c711a07af788104d52ba7028db6286081d8c298a8b1912b8444dc10edb55c36'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-09-22T00:00:00+00:00'::TIMESTAMPTZ, 'd49fd3ff0a6ddb4773f20b57c5f7ddacf006d11622d0236bf6b2ac639dc8981e'::TEXT, ARRAY[614]::BIGINT[]),
    (548::BIGINT, 'Muy mala profe. Muy mala actitud, se enreda cuando "explica" y se enoja si uno le pregunta. Califica como si fuera buena profe.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2015-08-22T00:00:00+00:00'::TIMESTAMPTZ, 'c94a18f0300f7bb2922b2fccb03756b4813047393ecf1a0eda69c74657ecbbe0'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'La tuve como profesora en laboratorio y me pareció bastante buena, igual califica rudo pero me pareció buena para lab'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, '86940ea880bd34ab430d9e47758084dcf41303d970eb5c7cecb71536c6aa8212'::TEXT, ARRAY[567]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, '243fdb27246e92dccb352f4839138c415b2f7e68b1fb47d8ab4f61bb98f499e4'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Se entiende lo que explica, el problema es que de todo lo que sale en el examen, explica la mitad, no se hace mucha practica, la parte teorica la tiene que buscar por otro lado, no da nada de teoria, y califica rudo.Quices no dan dificiles y casi no deja tareas.Si vas con ella, procure ir a tutoria'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'c542f346d84b91785c8ba4235acb101c8a320120692005d3c5e77d10d0baf4b4'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, '3cbb28677c0fc144615590c2aa4d8c61030bedf854bcb08ae7244f9f3105fbc0'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, '35fed0d60b5eef823ecef0cb4c9b9748b56804079302a9be08dfa82a461c56b5'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'En sí la profesora explica mal tirando a normal, pero califica totalmente rudo, es pasable si uno entiende por su cuenta o tiene a alguien que le explique por aparte.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'b2729b1d746481da24123991fd2bead2863fddd165b89156fdb0f3c8ac7064a6'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Explica muy mal, no atiende dudas y califica muy rudo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-17T00:00:00+00:00'::TIMESTAMPTZ, '5642d64a984992a097a8dc788369e192c2d63f599aea3b9a19209e12973c4e58'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Se enreda al explicar y los exámenes los califica como si fuera buena profesora'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'f4def62761c22ea1346a20f545575244959cfd5db6fd253675c65bbba77e03aa'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Le falta la vocación de profesora. Se enreda a la hora de explicar.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'ccae711137d5f2a23a3bb937a3474fa1865c3f18d9d5e4f04ef3ec9805fe81c5'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, '63ddc5ef50e326e45fa0b2eb8201bf900f41e21c4795d83db5ddfe8ce0b80fc6'::TEXT, ARRAY[568, 614]::BIGINT[]),
