    (548::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '3c451484e409727fd04ca2b15c77ef05f6eb2b15950437c97ac4a2b3d79370e6'::TEXT, ARRAY[568, 614]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-28T00:00:00+00:00'::TIMESTAMPTZ, '39dddb9592c84dd8e535d6a08165ad5129f530c4cd38fb8c0eb5d6ced2858e66'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'exigente, pero guia bien las clases en los laboratorios'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-23T00:00:00+00:00'::TIMESTAMPTZ, '28c1d14a1366e126ae6664f6cbbb9cebb29683cda7976f5d6bfdf370c190975c'::TEXT, ARRAY[567]::BIGINT[]),
    (548::BIGINT, 'Siempre llega tarde. A no va a consulta. Lo enreda a uno cuando se le hace una pregunta. No es tan mala explicando ya que se ve que tiene sus conocimientos. Sin embargo no la recomiendo a nadie. El curso se pasa siempre y cuando lleve la materia al día. Califica duro.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-17T00:00:00+00:00'::TIMESTAMPTZ, '4518c335202282ef5e34109791067d1dc80a99055d4d0e095c7210929fb4c192'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('5','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-13T00:00:00+00:00'::TIMESTAMPTZ, '59ca536a44748482cb0aa9501a143aa6d4b49bc3245f1322d2dd74964c290741'::TEXT, ARRAY[567]::BIGINT[]),
    (548::BIGINT, 'No gracias.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('5','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-11T00:00:00+00:00'::TIMESTAMPTZ, '3669732425b7ddb32b536b2dde5e13d1f833cdb6025593560f38574a9678366d'::TEXT, ARRAY[567]::BIGINT[]),
    (548::BIGINT, 'Siempre llega tarde , la explicación nunca queda clara y si preguntas es peor el enredo , nunca esta en consulta , entrega examenes cuando le da la gana y califica MUY duro no la recomiendo es muy mala!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'd895dbd479945a3daf6b0a8445cb6a5e90d3e9399220a4427507af4c9e506cc2'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'e9290f7e6d24806e60734ce0f1e14c7f88f4ae7c6dd6860a69db7e525f58f279'::TEXT, ARRAY[567]::BIGINT[]),
    (548::BIGINT, 'Tiene conocimientos, pero a la hora de hacerle una pregunta enreda al estudiante,'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'f5b4fad0ec35af083568cff6eddc8cc168505646ea9ae4486c6fd8250a9c3221'::TEXT, ARRAY[568]::BIGINT[]),
    (548::BIGINT, 'Muy pura vida, el que estudia pasa'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'c637554077d0f826c9c12ebd2fbe78065a61c2d2404210b544052f894170a002'::TEXT, ARRAY[568, 614]::BIGINT[]),
    (548::BIGINT, 'Solo llévelo con ella si no hay otra opción. No se le entiende, es muy enredado ¡DE VERAS! ¡NO LO HAGA! hay mejores profes'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, '6f55c6fc7655b7c9dbff47ac84063f9e895b540a6ba957123ea2bc397d7b8a8a'::TEXT, ARRAY[568]::BIGINT[]),
